 players.forEach((p,index)=>{const seat=document.createElement('div');seat.className='coop-seat'+(p?.id===credentials.playerId?' is-you':'');const label=document.createElement('strong'),sub=document.createElement('small');label.textContent=p?p.name+(p.id===credentials.playerId?' · VOCÊ':''):'ESPERANDO O PARCEIRO';sub.textContent=p?(p.id===credentials.playerId?ready:p.ready)?'✓ PRONTO PRA RESENHA':index===0?'CRIADOR DA DUPLA':'PREPARANDO O PAPEL':'PASSE O CÓDIGO ACIMA';seat.append(label,sub);$('coopSeats').append(seat);});
