function clearConnection(message=''){
 generation++;clearTimeout(pollTimer);net?.close?.();net=null;credentials=room=null;role=currentRole=null;world=targetWorld=null;predicted=predictionTarget=null;receivedMatch=null;smoothedPlayers=[];remoteInput=blankInput();remoteSequence=-1;input=blankInput();inputSeq=stateSeq=0;ready=false;restoring=false;busy=false;readyRevision=0;syncedReady=-1;failures=0;resetInputs();try{sessionStorage.removeItem(SESSION);}catch{}if(overlay){setArena(false);updateLobby();$('coopRestartBtn').hidden=true;if(message)setStatus(message,true);}
}
async function leaveRoom(message='Você saiu da dupla. Crie outra sala quando quiser.',closing=false){
 const old=credentials&&room?{token:credentials.token,code:room.code}:null;resetInputs();if(old){try{const options={method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+old.token},body:'{}'};if(location.protocol==='file:'&&window.DaRocaNetwork?.request)window.DaRocaNetwork.request('/api/arena/rooms/'+old.code+'/leave',options).catch(()=>{});else fetch((location.protocol==='file:'?OFFICIAL:'')+'/api/arena/rooms/'+old.code+'/leave',{...options,keepalive:true,cache:'no-store',credentials:'omit'}).catch(()=>{});}catch{}}clearConnection(closing?'':message);
}
async function request(path,options={}){
 const headers={'Content-Type':'application/json',...(options.headers||{})};if(credentials?.token)headers.Authorization='Bearer '+credentials.token;let response;
 if(location.protocol==='file:'&&window.DaRocaNetwork?.request)response=await window.DaRocaNetwork.request(path,{method:options.method||'POST',headers,body:options.body===undefined?undefined:JSON.stringify(options.body)});
 else{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{response=await fetch((location.protocol==='file:'?OFFICIAL:'')+path,{method:options.method||'POST',headers,body:options.body===undefined?undefined:JSON.stringify(options.body),signal:controller.signal,cache:'no-store',credentials:'omit'});}finally{clearTimeout(timer);}}
 let data;if(typeof response?.json==='function')data=await response.json();else{data=response?.body??response?.data??response;if(typeof data==='string')data=JSON.parse(data);}const status=response?.status??200;if(response?.ok===false||status>=400||data?.error){const error=new Error(data?.error?.message||data?.message||(typeof data?.error==='string'?data.error:'A sala não respondeu. Confira a internet.'));error.status=status;throw error;}return data;
}
async function connect(kind){
 if(busy||credentials)return;const code=$('coopCodeIn').value,name=clean($('coopName').value)||'Da Resenha';if(kind==='join'&&!/^[A-Z0-9]{6}$/.test(code)){setStatus('Digite as seis letras e números da sala do amigo.',true);$('coopCodeIn').focus();return;}busy=true;updateLobby();setStatus(kind==='create'?'Criando a dupla na nuvem…':'Entrando na dupla…');const gen=++generation;try{localStorage.setItem('daroca-coop-name',name);const data=await request(kind==='create'?'/api/arena/rooms':'/api/arena/rooms/'+code+'/join',{body:{name,character:'daroca',mode:'coop',protocol:PROTOCOL,capacity:2}});if(gen!==generation)return;if(data.room?.mode!=='coop'||data.room?.protocol!==PROTOCOL)throw Error('Atualize o jogo para entrar na nova Dupla online.');credentials={token:data.token,playerId:data.playerId,isHost:!!data.isHost};role=currentRole=data.isHost?'host':'guest';room=data.room;ready=false;readyRevision++;sessionStorage.setItem(SESSION,JSON.stringify({...credentials,code:room.code,hostPlayerId:room.hostPlayerId}));absorb(data);setStatus('Dupla '+room.code+' aberta. Passe o código e toquem em ESTOU PRONTO.');scheduleSync(120);}catch(error){if(gen===generation)setStatus(error.name==='AbortError'?'A internet demorou. Tente entrar novamente.':error.message,true);}finally{if(gen===generation){busy=false;updateLobby();}}
}
function createHost(){connect('create');}function prepareGuest(){if(credentials)return;$('coopPairing').hidden=false;setStatus('Peça o código da Dupla ao amigo. A Arena da Resenha usa outro tipo de sala.');$('coopCodeIn').focus();}function applyCode(){connect('join');}
async function copyCode(){const value=room?.code;if(!value)return;try{await navigator.clipboard.writeText(value);setStatus('Código copiado! O amigo abre Dupla online e digita '+value+'.');}catch{$('coopCodeOut').focus();$('coopCodeOut').select();setStatus('Código da dupla: '+value+'. Selecione para copiar.');}}
function setupNet(){if(net||!credentials||!window.ArenaNet)return;net=ArenaNet.create({code:room.code,playerId:credentials.playerId,hostPlayerId:room.hostPlayerId,players:room.players,isHost:role==='host',request,onInput:(id,command)=>{if(role==='host')acceptInput(id,command);},onState:state=>{if(role==='guest')receiveState(state);}});}
function wireInput(){const local=getLocalInput();return{seq:++inputSeq,x:(local.right?1:0)-(local.left?1:0),y:0,jump:!!local.jump,jumpPress:local.jumpPress,attack:local.paper,special:local.fart,dash:local.dash,ultimate:0,emote:0,aim:0};}
function decodeInput(i){return{seq:i.seq,left:i.x<-.1,right:i.x>.1,jump:!!i.jump,jumpPress:i.jumpPress||0,paper:i.attack||0,fart:i.special||0,dash:i.dash||0};}
