function validWorld(w){return w&&w.v===PROTOCOL&&w.mode==='coop'&&counter(w.seq)&&typeof w.matchId==='string'&&finite(w.time)&&Number.isInteger(w.wave)&&w.wave>=0&&w.wave<3&&['countdown','playing','intermission','victory','defeat'].includes(w.stage)&&Array.isArray(w.players)&&w.players.length===2&&w.players.every((p,id)=>p&&p.id===id&&['x','y','vx','vy','hp','gas'].every(k=>finite(p[k]))&&p.x>=0&&p.x<=960&&p.y>=0&&p.y<=540&&p.used&&['paper','fart','dash','jumpPress'].every(k=>counter(p.used[k])))&&w.boss&&bossTypes.includes(w.boss.type)&&['x','y','hp','max'].every(k=>finite(w.boss[k]))&&Array.isArray(w.shots)&&w.shots.length<=64&&w.shots.every(s=>s&&['x','y','vx','vy'].every(k=>finite(s[k])))&&Array.isArray(w.hazards)&&w.hazards.length<=25;}
function absorb(data){
 if(!data?.room||data.room.mode!=='coop'||data.room.protocol!==PROTOCOL||data.room.capacity!==2||!Array.isArray(data.room.players))throw Error('Esta sala usa outro modo ou versão. Atualize e abra Dupla online.');room=data.room;credentials.isHost=room.hostPlayerId===credentials.playerId;role=currentRole=credentials.isHost?'host':'guest';
 for(const entry of data.inputs||[])if(entry.playerId!==room.hostPlayerId&&entry.input)acceptInput(entry.playerId,entry.input);
 if(role==='guest'||restoring)receiveState(data.state);
 if(restoring){const own=(data.inputs||[]).find(i=>i.playerId===credentials.playerId),used=world?.players[localSlot()]?.used;inputSeq=Math.max(inputSeq,own?.seq||0);for(const[a,b]of[['paper','attack'],['fart','special'],['dash','dash'],['jumpPress','jumpPress']])input[a]=Math.max(input[a],own?.input?.[b]||0,used?.[a]||0);ready=!!room.players.find(p=>p.id===credentials.playerId)?.ready;restoring=false;readyRevision++;setStatus('Você voltou à mesma dupla. A resenha continua.');}
 if(room.players.length<2&&world){world=targetWorld=null;predicted=null;setArena(false);setStatus('O parceiro saiu. Passe o mesmo código para outro amigo e fiquem prontos.');ready=false;readyRevision++;}
 if(!room.hostConnected){resetInputs();setStatus('Aguardando o celular que criou a dupla voltar…',true);}else if(failures)setStatus('Conexão recuperada. A resenha continua.');
 setupNet();net?.updateRoster?.(room.players);updateLobby();failures=0;
}
function receiveState(incoming){
 if(!validWorld(incoming)||world&&incoming.seq<=world.seq)return;const changed=receivedMatch!==incoming.matchId;world=incoming;world.fx=[];targetWorld=world;stateSeq=Math.max(stateSeq,incoming.seq);lastStateAt=performance.now();
 if(changed){receivedMatch=world.matchId;smoothedPlayers=[];predicted=null;predictionTarget=null;resetInputs();}
 if(role==='guest')reconcilePrediction(world.players[1]);if(!arenaVisible())setArena(true);$('coopRoleLabel').textContent=role==='host'?'VOCÊ · DA ROÇA 1':'VOCÊ · PARCEIRO 2';
}
function snapshot(){
 if(!world)return null;world.seq=++stateSeq;world.serverTime=serverNow();const snap={...world,players:world.players.map(p=>({...p,used:{...p.used}})),shots:world.shots.slice(-56),hazards:world.hazards.slice(-20),fx:[]};
 // Fixed-size effects stay local; only gameplay objects travel over the fallback.
 return JSON.parse(JSON.stringify(snap,(key,value)=>typeof value==='number'?Math.round(value*1000)/1000:value));
}
function scheduleSync(delay=180){clearTimeout(pollTimer);if(opened&&credentials)pollTimer=setTimeout(sync,Math.max(delay,125-(performance.now()-lastRequestAt)));}
function syncNow(){if(!credentials)return;urgent=true;if(!syncing)scheduleSync(0);}
async function sync(){
 if(!opened||!credentials)return;if(syncing){urgent=true;return;}syncing=true;urgent=false;lastRequestAt=performance.now();const gen=generation,body=restoring?{}:{input:wireInput()},revision=readyRevision;
 if(!restoring&&syncedReady!==revision)body.ready=ready;if(role==='host'&&!restoring){if(world){body.state=snapshot();body.status=['victory','defeat'].includes(world.stage)?'finished':'playing';}else body.status='lobby';}
 const started=performance.now(),wall=Date.now();try{const data=await request('/api/arena/rooms/'+room.code+'/sync',{body});if(gen!==generation)return;const elapsed=performance.now()-started;rttMs=rttMs?rttMs*.7+elapsed*.3:elapsed;if(finite(data.serverTime))serverOffset=data.serverTime-(wall+Date.now())/2;if(body.ready!==undefined)syncedReady=revision;absorb(data);}catch(error){if(gen!==generation)return;failures++;if([401,403,404,410].includes(error.status)){clearConnection('A dupla foi encerrada ou expirou. Crie outra sala pelo celular.');return;}setStatus(error.name==='AbortError'?'A internet demorou. Reconectando a dupla…':error.message||'Conexão oscilando. Reconectando…',true);}finally{syncing=false;}
 if(gen===generation&&credentials){const link=net?.getStatus?.(),cadence=!world?500:link?.connected>=1?500:180;scheduleSync(urgent?0:Math.max(0,Math.min(cadence*Math.max(1,failures),2500)-(performance.now()-lastRequestAt)));}
}
function player(id,x){return{id,x,y:FLOOR,vx:0,vy:0,ground:true,facing:id===0?1:-1,hp:180,max:180,gas:100,paperCD:0,fartCD:0,dashCD:0,dashTime:0,inv:1,attack:0,attackKind:'paper',lastJump:false,used:{paper:0,fart:0,dash:0,jumpPress:0},ackSeq:0,down:0,anim:0,moveX:0};}
