 if(role!=='host'||!isConnected()||room.players.some(p=>p.id===credentials.playerId?!ready:!p.ready))return;resetInputs();const local=getLocalInput(),players=[player(0,210),player(1,350)];for(const p of players){const command=p.id?remoteInput:local;for(const a of ['paper','fart','dash','jumpPress'])p.used[a]=command[a]||0;}
 const matchId=window.crypto?.randomUUID?.()||Date.now().toString(36);world={v:PROTOCOL,mode:'coop',seq:stateSeq,matchId,serverTime:serverNow(),startAt:serverNow()+3200,time:0,tick:0,wave:0,stage:'countdown',stageTimer:0,players,boss:boss(0),shots:[],hazards:[],fx:[],nextShot:1};receivedMatch=matchId;targetWorld=world;smoothedPlayers=[];predicted=null;lastStateAt=performance.now();setArena(true);$('coopRoleLabel').textContent='VOCÊ · DA ROÇA 1';net?.sendState?.(snapshot());syncNow();
