function resetStick(){joystickPointer=null;joyCenter=null;joyX=0;if($('coopJoystick')){$('coopJoystick').style.setProperty('--stick-x','0px');$('coopJoystick').style.setProperty('--stick-y','0px');$('coopJoystick').setAttribute('aria-valuenow','0');}}
function moveStick(e){if(!joyCenter)return;joyX=clamp((e.clientX-joyCenter.x)/joyCenter.r,-1,1);if(Math.abs(joyX)<.15)joyX=0;$('coopJoystick').style.setProperty('--stick-x',(joyX*joyCenter.r)+'px');$('coopJoystick').style.setProperty('--stick-y',clamp(e.clientY-joyCenter.y,-joyCenter.r*.3,joyCenter.r*.3)+'px');$('coopJoystick').setAttribute('aria-valuenow',String(Math.round(joyX*100)));changedInput();}
function actionHeld(action){return [...pressedKeys].some(code=>keyMatches(action,code));}
function releasePointer(id){const p=activePointers.get(id);if(!p)return;activePointers.delete(id);if(![...activePointers.values()].some(v=>v.el===p.el))p.el.classList.remove('pressed');if(p.action==='jump')input.jump=actionHeld('jump')||[...activePointers.values()].some(v=>v.action==='jump');changedInput();}
function resetInputs(){input.left=input.right=input.jump=false;pressedKeys.clear();for(const p of activePointers.values())p.el.classList.remove('pressed');activePointers.clear();resetStick();changedInput();}
function changedInput(){if(!opened||!credentials)return;if(role==='guest')net?.sendInput?.(wireInput());syncNow();}
function pulse(action){if(!arenaVisible()||!['paper','fart','dash'].includes(action)||world?.stage!=='playing')return;input[action]++;changedInput();}
function getLocalInput(){return{...input,seq:inputSeq,left:joyX<-.15||input.left,right:joyX>.15||input.right};}
const defaults={left:['KeyA','ArrowLeft'],right:['KeyD','ArrowRight'],jump:['Space','KeyW','ArrowUp'],paper:['KeyJ'],fart:['KeyK'],dash:['KeyL','ShiftLeft','ShiftRight']};
function keyMatches(action,code){return window.ControlSettings?.matches?ControlSettings.matches(action,code):defaults[action]?.includes(code);}
function readHeld(){input.left=actionHeld('left');input.right=actionHeld('right');input.jump=actionHeld('jump')||[...activePointers.values()].some(v=>v.action==='jump');}
document.addEventListener('keydown',e=>{if(!opened)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return;}if(!arenaVisible()||e.target.closest?.('textarea,input'))return;const actions=Object.keys(defaults).filter(a=>keyMatches(a,e.code));if(!actions.length)return;e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;const wasJump=input.jump;pressedKeys.add(e.code);readHeld();if(input.jump&&!wasJump)input.jumpPress++;for(const action of actions)if(['paper','fart','dash'].includes(action))pulse(action);changedInput();},true);
